package com.abogacia.microservicio_ciudadanos.correo;
import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;import static org.mockito.ArgumentMatchers.*;import java.util.*;
import com.abogacia.microservicio_ciudadanos.repository.CiudadanoRepository;import com.abogacia.microservicio_ciudadanos.entity.*;
class ReenvioSeguroTest {
 @Test void correoDesconocidoNoEnvia(){var r=mock(CiudadanoRepository.class);var mail=mock(InterfazCorreo.class);new ReenviarConfirmacion(r,mail,mock(org.springframework.security.crypto.password.PasswordEncoder.class)).enviar("fixture@example.invalid");verifyNoInteractions(mail);}
 @Test void confirmadoNuncaRotaCodigo(){var r=mock(CiudadanoRepository.class);var mail=mock(InterfazCorreo.class);var a=new Ciudadano();a.setCorreoConfirmado(true);when(r.findByMailForUpdate(anyString())).thenReturn(Optional.of(a));new ReenviarConfirmacion(r,mail,mock(org.springframework.security.crypto.password.PasswordEncoder.class)).enviar("fixture@example.invalid");verifyNoInteractions(mail);verify(r,never()).saveAndFlush(any());}
 @Test void reenvioRotaTokenYRespetaEspera(){var r=mock(CiudadanoRepository.class);var mail=mock(InterfazCorreo.class);var a=new Ciudadano();a.setEstado(new Estado("PENDIENTE"));a.setCodigoConfirmacion("anterior-vencido");when(r.findByMailForUpdate(anyString())).thenReturn(Optional.of(a));var service=new ReenviarConfirmacion(r,mail,mock(org.springframework.security.crypto.password.PasswordEncoder.class));service.enviar("fixture@example.invalid");var code=org.mockito.ArgumentCaptor.forClass(String.class);verify(mail).enviarMailConfirmacion(any(),code.capture());assertNotEquals(code.getValue(),a.getCodigoConfirmacion());assertTrue(TokenCorreo.vigente(a.getCodigoConfirmacion()));service.enviar("fixture@example.invalid");verify(mail,times(1)).enviarMailConfirmacion(any(),anyString());}
}
